    public AAWebClientUrlResponse getAAClientWebUrlByAAId( @NotNull String vua, String token ) throws DataException
    {
        String entityId = jwtTokenUtil.getFiuIdFromToken(token);
        Optional<EntityDetails> entityDetailsOptional = entityDetailsRepository
                .findByEntityId(entityId);
        if( !entityDetailsOptional.isPresent() )
        {
            throw new DataException(HttpStatus.BAD_REQUEST.getReasonPhrase(),
                    "entity details not present in web url api fetch", HttpStatus.BAD_REQUEST);
        }
        AAWebClientUrlResponse aaWebClientUrlResponse = new AAWebClientUrlResponse();
        if( NullEmptyUtils.isNullorEmpty(vua) )
        {
            if(entityDetailsOptional.get().getIsFinsoftEnable()){
                aaWebClientUrlResponse.setInitWebSdk(false);
            } else {
                aaWebClientUrlResponse.setInitWebSdk(true);
            }
            aaWebClientUrlResponse.setAaClientWebUrl(defaultAAUrl);
        }
        else
        {
//            String aaVuaHandle = consentInitService.validateCustomerId(vua);
//            AACrEntityCollection aaCrEntityCollection = aaCrEntityRepository.findByEntityVuaHandle(aaVuaHandle);
//            if(NullEmptyUtils.isNullorEmpty((Collection<?>) aaCrEntityCollection)) {
//                throw new DataException(GeneralConstants.INVALID_REQUEST, "Invalid Request", HttpStatus.BAD_REQUEST);
//            }
            aaWebClientUrlResponse.setAaClientWebUrl(defaultAAUrl);
            if(vua.contains("onemoney")){
                aaWebClientUrlResponse.setInitWebSdk(true);
            }else{
                aaWebClientUrlResponse.setInitWebSdk(false);
            }
            //aaWebClientUrlResponse.setAaClientWebUrl(aaCrEntityCollection.getEntityinfo().getWebviewurl());
        }
        return aaWebClientUrlResponse;
    }

    @Override
    public OneMoneyConfigeResponse getOneMoneyConfigDetails(String fiuAccessToken) throws DataException {
        String entityId = jwtTokenUtil.getFiuIdFromToken(fiuAccessToken);
        if(NullEmptyUtils.isNull(entityId)){
            throw new DataException(GeneralConstants.BAD_REQUEST, "fiuId is null in access token",
                    HttpStatus.BAD_REQUEST);
        }
        Optional<EntityDetails> entityDetailsOptional = entityDetailsRepository
                .findByEntityId(entityId);

        if( !entityDetailsOptional.isPresent() )
        {
            throw new DataException(HttpStatus.BAD_REQUEST.getReasonPhrase(),
                    "entity details not present", HttpStatus.BAD_REQUEST);
        }
        return mapOneMoneyConfigResponse(entityDetailsOptional.get(),applicationConfigurationBean);

